  buildUpdates?: (body: Record<string, unknown>, auth: AuthContext) => Record<string, unknown>;
  buildMetadata?: (body: Record<string, unknown>, auth: AuthContext) => Record<string, unknown>;
};

/**
 * Factory for workflow action route handlers.
 * Reduces boilerplate: each action endpoint is just a config object.
 */
export function createWorkflowAction(config: WorkflowActionConfig) {
  return async (
    request: NextRequest,
    { params }: { params: Promise<{ slug: string; id: string }> }
  ) => {
    try {
      const auth = await getAuthUser();
      if (!auth) {
        return NextResponse.json(
          { error: "Authentication required" },
          { status: 401 }
        );
      }

      const { slug, id: requestId } = await params;
      const tenant = await resolveTenant(slug);
      if (!tenant) {
        return NextResponse.json(
          { error: "Organisation not found" },
          { status: 404 }
        );
      }

      if (config.requiredAnyPermission) {
        const permResult = checkAnyPermission(
          auth,
          tenant.id,
          config.requiredAnyPermission
        );
        if (!permResult.granted) {
          return NextResponse.json(
            { error: permResult.reason },
            { status: 403 }
          );
        }
      } else if (config.requiredPermission) {
        const permResult = checkPermission(
          auth,
          tenant.id,
          config.requiredPermission
        );
        if (!permResult.granted) {
          return NextResponse.json(
            { error: permResult.reason },
            { status: 403 }
          );
        }
      }

      // Parse body if schema provided
      let body: Record<string, unknown> = {};
      if (config.bodySchema) {
        let raw: unknown = {};
        try {
          raw = await request.json();
        } catch {
          // Empty body is valid for optional schemas
        }
        const parsed = config.bodySchema.safeParse(raw);
        if (!parsed.success) {
          return NextResponse.json(
            { error: "Validation failed", details: parsed.error.flatten() },
            { status: 400 }
          );
        }
        body = parsed.data;
      }

      const updated = await withTenant(tenant.id, async (tx) => {
        return transitionRequest(tx, {
          requestId,
          tenantId: tenant.id,
          event: config.event,
          actorId: auth.user.id,
          updates: config.buildUpdates?.(body, auth),
          metadata: config.buildMetadata?.(body, auth) ?? body,
        });
      });

      return NextResponse.json({ request: updated });
    } catch (err: unknown) {
      const message =
        err instanceof Error ? err.message : "Internal server error";

      if (message.includes("Cannot") || message.includes("not found")) {
        return NextResponse.json({ error: message }, { status: 400 });
      }

      console.error("Workflow action error:", err);
      return NextResponse.json(
        { error: "Internal server error" },
        { status: 500 }
      );
    }
  };
}
