"use client";

import { useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import {
  Elements,
  PaymentElement,
  useStripe,
  useElements,
} from "@stripe/react-stripe-js";
import { loadStripe } from "@stripe/stripe-js";
import { Button } from "@/components/ui/button";
import { CardTitle } from "@/components/ui/card";

type PaymentStepProps = {
  clientSecret: string;
  amount: number; // in cents
  tenantSlug: string;
  stripeAccountId?: string | null;
};

// Lazy-load Stripe instance. When a connected account is provided, Stripe.js
// must be initialised with that account so it can find the payment intent.
const stripePublishableKey = process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY;
const stripeCache = new Map<string, ReturnType<typeof loadStripe>>();

function getStripePromise(connectedAccount?: string | null) {
  if (!stripePublishableKey) return null;
  const key = connectedAccount ?? "__platform__";
  if (!stripeCache.has(key)) {
    stripeCache.set(
      key,
      connectedAccount
        ? loadStripe(stripePublishableKey, { stripeAccount: connectedAccount })
        : loadStripe(stripePublishableKey)
    );
  }
  return stripeCache.get(key)!;
}

function PaymentForm({ amount, tenantSlug }: { amount: number; tenantSlug: string }) {
  const stripe = useStripe();
  const elements = useElements();
  const router = useRouter();
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [succeeded, setSucceeded] = useState(false);
  const [elementReady, setElementReady] = useState(false);

  const handleSubmit = useCallback(async () => {
    if (!stripe || !elements) return;

    setProcessing(true);
    setError(null);

    const { error: submitError } = await elements.submit();
    if (submitError) {
      setError(submitError.message ?? "Payment failed");
      setProcessing(false);
      return;
    }

    const { error: confirmError } = await stripe.confirmPayment({
      elements,
      confirmParams: {
        return_url: `${window.location.origin}/t/${tenantSlug}/dashboard`,
      },
      redirect: "if_required",
    });

    if (confirmError) {
      setError(confirmError.message ?? "Payment failed");
      setProcessing(false);
      return;
    }

    // Payment succeeded (no redirect needed)
    setSucceeded(true);
    setProcessing(false);

    // Redirect after a brief confirmation
    setTimeout(() => {
      router.push(`/t/${tenantSlug}/dashboard`);
    }, 2000);
  }, [stripe, elements, tenantSlug, router]);

  if (succeeded) {
    return (
      <div className="space-y-4 text-center py-8">
        <div className="mx-auto h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center text-2xl text-primary">
          {"\u2713"}
        </div>
        <CardTitle className="text-lg">Payment Successful</CardTitle>
        <p className="text-sm text-muted-foreground">
          Your payment of ${(amount / 100).toFixed(2)} has been processed. Redirecting to your dashboard...
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="space-y-2">
        <CardTitle className="text-lg">Payment Required</CardTitle>
        <p className="text-sm text-muted-foreground">
          Please complete payment of{" "}
          <span className="font-semibold text-foreground">
            ${(amount / 100).toFixed(2)}
          </span>{" "}
          to proceed with your request.
        </p>
      </div>

      <PaymentElement
        onReady={() => setElementReady(true)}
        onLoadError={(e: { error?: { message?: string } }) => setError(e.error?.message ?? "Payment form failed to load. The club's payment account may not be fully set up yet.")}
      />

      {error && (
        <p className="text-sm text-destructive">{error}</p>
      )}

      <Button
        onClick={handleSubmit}
        disabled={!stripe || !elementReady || processing}
        className="w-full"
      >
        {processing ? "Processing..." : `Pay $${(amount / 100).toFixed(2)}`}
      </Button>
    </div>
  );
}

export function PaymentStep({ clientSecret, amount, tenantSlug, stripeAccountId }: PaymentStepProps) {
  const stripePromise = getStripePromise(stripeAccountId);
  if (!stripePromise) {
    return (
      <div className="space-y-4 text-center py-8">
        <CardTitle className="text-lg">Payment Required</CardTitle>
        <p className="text-sm text-muted-foreground">
          Payment of ${(amount / 100).toFixed(2)} is required for this request.
          Payment will be collected separately. Please contact your club administrator.
        </p>
      </div>
    );
  }

  return (
    <Elements
      stripe={stripePromise}
      options={{
        clientSecret,
        appearance: {
          theme: "stripe",
          variables: {
            colorPrimary: "#0d9488",
          },
        },
      }}
    >
      <PaymentForm amount={amount} tenantSlug={tenantSlug} />
    </Elements>
  );
}

