export function paymentReminderEmail(
  clubName: string,
  memberName: string,
  amount: string
): string {
  const body = `
    <h1 style="${heading()}">Payment Reminder</h1>
    <p style="${bodyText()}">
      Dear ${memberName.split(" ")[0]},
    </p>
    <p style="${bodyText()}">
      Reminder: Your request requires payment of <strong>${amount}</strong> to proceed.
    </p>
    <div style="margin: 0 0 16px; padding: 12px 16px; background-color: #f0fdfa; border-left: 3px solid ${getPrimaryColour()}; border-radius: 4px;">
      <p style="margin: 0; color: #134e4a; font-size: 13px;"><strong>Amount due:</strong> ${amount}</p>
    </div>
    <p style="${mutedText()}">
      Please complete your payment so your request can be reviewed. If you have already paid, please disregard this message.
    </p>`;
  return layout(clubName, body);
}

