// When payment becomes due (exemption rejected, or an admin / the nightly
// abandoned-payment sweep requires payment), make sure a Stripe payment
// intent exists and the amount is recorded so the public pay page can
// render. REJECT_EXEMPTION keeps its historical lenience (no price means no
// intent); PAYMENT_REQUIRED is an explicit demand for money, so a missing
// price is an error and the whole transition rolls back.
if (params.event === "REJECT_EXEMPTION" || params.event === "PAYMENT_REQUIRED") {
  const ensured = await ensurePaymentIntent(tx, {
    request,
    tenantId: params.tenantId,
  });
  if (!ensured && params.event === "PAYMENT_REQUIRED") {
    throw new Error(
      "Cannot require payment: no price is configured for this request's credential type"
    );
  }
}

